# Hand-written R5900 versions of the emu_tests.c kernels (bench variants asm
# and asm-vu0: no VU0), generated by asm/gen/app_files.py from asm/gen/
# emu.py. n32 ABI. The kernels use the data of emu_tests.c (KERNEL_DATA).
# The interpreters dispatch through jump tables in .rodata.
# Optimized: yes, all. Measured on the PS2 (asm/harness/app.c), feature
# clang in parentheses:
#   6502 Interp   21.0 MIPS (14.7)    threaded dispatch, branchless branches
#   R3000 Interp  15.3 MIPS (10.4)    threaded, the next instruction fetched
#                                     first, one table for opcode and funct
#   SNES Tiles    74.6 Mpix/s (47.5)  a table of 256 doublewords
#   N64 To CT16   55.1 Mpix/s (48.8)  MMI, the study of hand/gen_n64.py
#   Guest Loads   23.8 Mload/s (17.5) MMI byte swap, PREF of guest_addr 2
#                 lines and of the host word 16 loads ahead (no host PREF:
#                 19.7; scalar byte swap 21.7)

	.set	noreorder
	.set	noat

# gfx_mem: the offsets of its buffers
#define SPRITE		0x0000
#define FRAME		0x4400
#define INDEXED		0x8800
#define PALETTE		0x9c00
#define FRAME16		0xa000
#define SCALED		0xc400
# geom_mem
#define VERTS		0x0000
#define NORMALS		0x2400
#define SCALED_V	0x4800
#define FACE_NORMALS	0x6c00
#define SCREEN		0x9400
#define XFORMED		0xb800
#define COLORS		0xdc00
#define FACE_NORMALS_V	0xec00
#define VISIBLE		0x10c00

# reg = symbol + offset (any 32-bit offset), using $1
#define ADDR(reg, sym, off) \
	lui	$1, %hi(sym); addiu reg, $1, %lo(sym); \
	lui	$1, ((off) >> 16); ori $1, $1, ((off) & 0xffff); addu reg, reg, $1

